from pathlib import Path
import re, json, subprocess, os
p=Path('/opt/telegram-leads-optin')
active=Path('/opt/telegram-robot-leads')
print('PROVENANCE_BEGIN')
try:
 for line in (p/'PROVENANCE.txt').read_text().splitlines()[:10]: print(line[:180])
except OSError as e: print(type(e).__name__)
