for f in sorted((p/'scripts').glob('*')):
 if not f.is_file(): continue
 print('UTILITY',f.name)
 for line in f.read_text(errors='replace').splitlines()[:36]:
  if any(t in line.lower() for t in ('argparse','def main','def ','import ','description=','usage:','opt-in','optin','growth','health','status')):
   print(' ',line[:160])
for f in (active/'scripts/telegram-robot-leads-status.sh',active/'scripts/growth_radar.py',active/'docs/OPT_IN_GROWTH.md'):
 print('REFERENCE_FILE',str(f),f.exists())
 if not f.is_file(): continue
 lines=f.read_text(errors='replace').splitlines()
 for i,line in enumerate(lines):
  if '/opt/telegram-leads-optin' in line:
   print(' REFERENCE_LINE',i+1,line[:240])
   for nextline in lines[i+1:i+3]: print(' NEXT_LINE',nextline[:200])
print('ACTIVE_SCRIPT_IMPORT_REFERENCES')
for f in [active/'scripts/growth_radar.py',active/'scripts/telegram-robot-leads-status.sh']:
 if f.exists():
  t=f.read_text(errors='replace')
  print(f.name,'fallback:', 'fallback' in t.lower(),'optin:', 'optin' in t.lower(),'growth_store:', 'growth_store' in t.lower())
