 r=subprocess.run(['pm2','jlist'],capture_output=True,text=True,timeout=12,env={**os.environ,'PM2_HOME':'/root/.pm2'})
 if r.returncode==0:
  for app in json.loads(r.stdout):
   name=app.get('name','')
   if 'telegram' in name.lower() or 'iptvpn' in name.lower():
    env=app.get('pm2_env') or {}
    print(name,'status',env.get('status'),'cwd',env.get('pm_cwd'),'script',env.get('pm_exec_path'))
 else: print('PM2_QUERY_FAILED',r.returncode)
except Exception as e: print('PM2_QUERY_EXCEPTION',type(e).__name__)
print('AUDIT_DONE')
